function dkWire(world, opts) {
  opts = opts || {};
  var parts = {};
  world.querySelectorAll('[data-slug]').forEach(function (o) { (parts[o.dataset.slug] = parts[o.dataset.slug] || []).push(o); });
  var active = null, timer = 0;
  function light(slug, from) {
    clearTimeout(timer);
    if (slug === active) return;
    if (active) parts[active].forEach(function (o) { o.classList.remove('is-lit'); });
    active = slug;
    if (slug) parts[slug].forEach(function (o) { o.classList.add('is-lit'); });
    if (opts.onLight) opts.onLight(slug, from);
  }
  world.addEventListener('pointerover', function (e) {
    if (e.pointerType && e.pointerType !== 'mouse') return;
    var o = e.target.closest && e.target.closest('.dk-obj');
    if (o) light(o.dataset.slug, 'world');
  });
  world.addEventListener('pointerout', function (e) {
    var to = e.relatedTarget && e.relatedTarget.closest && e.relatedTarget.closest('.dk-obj');
    if (!to) { clearTimeout(timer); timer = setTimeout(function () { light(null, 'world'); }, 120); }
  });
  world.addEventListener('click', function (e) {
    var o = e.target.closest && e.target.closest('.dk-obj');
    if (o && opts.onPick) opts.onPick(o.dataset.slug);
  });
  return { light: light };
}
